/* Gamestage fonts: DM Sans (interface text) and Unbounded (numbers a player
   tracks: score, timer, rank, multiplier, level), linked from Google Fonts
   rather than self-hosted (BDS-005). Weights mirror examples/lab/index.html.
   Import this once at the root, before gamestage-tokens.css, so the family
   names tokens.css declares are already loaded.

   A stylesheet cannot express a preconnect hint: hosts that control their own
   <head> should also add
     <link rel="preconnect" href="https://fonts.googleapis.com" />
   themselves. */
@import url("https://fonts.googleapis.com/css2?family=DM+Sans:wght@400..900&family=Unbounded:wght@500..900&display=swap");
